// Pre: n >= 0
// Post: devuelve el numero de pares de digitos consecutivos distintos de n
int canvis(int n) {
    int res = 0;
    while (n >= 10) {
        if (n%10 != (n/10)%10) ++res;
        n = n/10;
    }
    return res;
}

int main() {
    int m;
    cin >> m;
    for (int i = 0; i < m; ++i) {
        int n;
        cin >> n;
        cout << canvis(n) << endl;
    }
}

