#include <iostream>
using namespace std;

// Pre: x >= 0, y >= 0
// Post: devuelve la suma de |dx - dy| sobre las posiciones de digitos de x e y,
//       completando con ceros el numero mas corto
int difDigits(int x, int y) {
    if (x == 0 and y == 0) return 0;
    int a = x%10;
    int b = y%10;
    int d = a - b;
    if (d < 0) d = -d;
    return d + difDigits(x/10, y/10);
}

int main() {
    int x, y;
    cin >> x >> y;
    cout << difDigits(x, y) << endl;
}

