#include <iostream>

// @pre: s es una string terminada en '\0'
// @post: retorna un puntero a la primera ocurrencia de c en s, o NULL si no está
char    *ft_strchr(const char *s, int c)
{
        const char    *pstr;

        pstr = s;
        while (*pstr)
        {
                if (*pstr == (unsigned char)c)
                        return ((char *)pstr);
                pstr++;
        }
        if ((unsigned char)c == '\0')
                return ((char *)pstr);
        return (NULL);
}

// @pre: std::cin contiene una secuencia de caracteres sin espacios terminada en '.'
// @post: consume la secuencia hasta '.' y retorna la longitud de la racha más larga de 'a' consecutivas
int     ft_secuencia(void)
{
        char    c;
        int     actual;
        int     maxima;

        actual = 0;
        maxima = 0;
        std::cin >> c;
        while (c != '.')
        {
                if (ft_strchr("a", c) != NULL)
                {
                        actual++;
                        if (actual > maxima)
                                maxima = actual;
                }
                else
                        actual = 0;
                std::cin >> c;
        }
        return (maxima);
}

int     main(void)
{
        std::cout << ft_secuencia() << std::endl;
        return (0);
}
